  n <- length(x)
  h_prime <- numeric(n)

  # Use central differences where possible
  for (i in 1:n) {
    if (i == 1) {
      # Forward difference
      h_prime[i] <- (h[i + 1] - h[i]) / (x[i + 1] - x[i])
    } else if (i == n) {
      # Backward difference
