arguments.old_content:
compute_derivatives <- function(x, h) {
  n <- length(x)
  h_prime <- numeric(n)

  # Use central differences where possible
  for (i in 1:n) {
    if (i == 1) {
      # Forward difference
      h_prime[i] <- (h[i + 1] - h[i]) / (x[i + 1] - x[i])
    } else if (i == n) {
      # Backward difference
      h_prime[i] <- (h[i] - h[i - 1]) / (x[i] - x[i - 1])
    } else {
      # Central difference
      h_prime[i] <- (h[i + 1] - h[i - 1]) / (x[i + 1] - x[i - 1])
    }
  }

  return(h_prime)
}

arguments.new_content:
compute_derivatives <- function(x, h) {
  n <- length(x)
  h_prime <- numeric(n)

  # Use central differences where possible
  for (i in 1:n) {
    if (i == 1) {
      # Forward difference
      h_prime[i] <- (h[i + 1] - h[i]) / (x[i + 1] - x[i])
    } else if (i == n) {
      # Backward difference
      h_prime[i] <- (h[i] - h[i - 1]) / (x[i] - x[i - 1])
    } else {
      # Central difference
      h_prime[i] <- (h[i + 1] - h[i - 1]) / (x[i + 1] - x[i - 1])
    }
  }

  cat("  [DERIVATIVE DIAGNOSTIC] x:", x, "\n")
  cat("  [DERIVATIVE DIAGNOSTIC] h:", h, "\n")
  cat("  [DERIVATIVE DIAGNOSTIC] h_prime:", h_prime, "\n")
  cat("  [DERIVATIVE DIAGNOSTIC] any NA/Inf in h_prime:", any(!is.finite(h_prime)), "\n")

  return(h_prime)
}

